+import { appendFileSync } from 'node:fs';
+import { pathToFileURL } from 'node:url';
+
+// Only canonical version-mirror candidates reach this gate. Builds intentionally
+// suppresses platform fan-out; database rollback requires an actual migration.
+export const REQUIRED_CI = {
+  'lint.yml': ['Backend, Shared, API Client, and Mobile Typecheck'],
+  'tests.yml': ['Classify Test Inputs', 'Backend Tests', 'Mobile Tests'],
+  'builds.yml': ['Classify Build Inputs', 'Release Configuration'],
+  'container-scan.yml': ['Classify Production Image Inputs', 'High and Critical Vulnerabilities'],
+  'database-upgrade.yml': ['Classify Database Inputs', 'Populated Postgres Upgrade'],
+};
+const ALLOWED_SKIPS = {
+  'builds.yml': [
+    'Backend Build', 'Expo Web Build', 'Web Critical Smoke',
+    'Full Exported Web and PWA End-to-End', 'Six-State Data-Backed Route Acceptance',
+    'UX Accessibility and Visual Regression', '${{ matrix.platform }} Runtime Bundle',
+    'Mobile Build', 'iOS Build', 'Wear Build and JVM Tests',
+    'Android Emulator End-to-End', 'Wear Release Emulator Smoke', 'Native Two-Emulator Package Upgrade',
+  ],
+  'database-upgrade.yml': ['v0.14.0 Upgrade and Encrypted Rollback'],
+};
+
+export function assertIdentity({ pull, master }, identity) {
+  const { repository, head, base, branch } = identity;
+  if (pull.state !== 'open' || pull.merged || pull.draft ||
+      pull.head?.sha !== head || pull.head?.ref !== branch ||
+      pull.head?.repo?.full_name !== repository || pull.base?.repo?.full_name !== repository ||
+      pull.base?.ref !== 'master' || pull.base?.sha !== base || master.object?.sha !== base) {
+    throw new Error('Release PR/head/base changed; no merge permitted. Inspect the candidate before recovery.');
+  }
+}
+
+function assertRunIdentity(run, identity) {
+  const associated = run.pull_requests;
+  const pull = associated?.[0];
+  const repositoryId = run.head_repository?.id;
+  if (!Array.isArray(associated) || associated.length !== 1 ||
+      !Number.isSafeInteger(repositoryId) || repositoryId <= 0 ||
+      pull?.number !== Number(identity.number) ||
+      pull.head?.sha !== identity.head || pull.head?.ref !== identity.branch ||
+      pull.base?.sha !== identity.base || pull.base?.ref !== 'master' ||
+      pull.head?.repo?.id !== repositoryId || pull.base?.repo?.id !== repositoryId ||
+      run.head_sha !== identity.head || run.head_branch !== identity.branch ||
+      run.head_repository?.full_name !== identity.repository || run.event !== 'pull_request') {
+    throw new Error(`CI run lacks the exact single PR/base identity: ${run.html_url}. No merge permitted.`);
+  }
+}
+
+export function evaluateRuns(runs, identity) {
+  const selected = [];
+  const pending = [];
+  for (const [file, requiredJobs] of Object.entries(REQUIRED_CI)) {
+    const candidates = runs.filter(run => run.path === `.github/workflows/${file}` &&
+      run.event === 'pull_request' && run.head_sha === identity.head &&
+      run.head_branch === identity.branch && run.head_repository?.full_name === identity.repository);
+    const run = candidates.sort((a, b) => b.id - a.id)[0];
+    if (!run || run.status !== 'completed') {
+      pending.push(`${file}: ${run?.status ?? 'missing'}${run ? ` (${run.html_url})` : ''}`);
+      continue;
+    }
+    if (run.conclusion !== 'success') {
+      throw new Error(`${file}: ${run.conclusion}; inspect ${run.html_url}, including approval/no-job annotations.`);
+    }
+    assertRunIdentity(run, identity);
+    const jobs = run.jobs ?? [];
+    for (const name of requiredJobs) {
+      if (!jobs.some(job => job.name === name && job.status === 'completed' && job.conclusion === 'success')) {
+        throw new Error(`${file}: required job ${name} did not succeed (${run.html_url}).`);
+      }
+    }
+    for (const job of jobs) {
+      if (job.status !== 'completed' || (job.conclusion !== 'success' &&
+          !(job.conclusion === 'skipped' && ALLOWED_SKIPS[file]?.includes(job.name)))) {
+        throw new Error(`${file}: unacceptable job ${job.name}: ${job.conclusion} (${run.html_url}).`);
+      }
+    }
+    selected.push(run);
+  }
+  return { selected, pending };
+}
+
+export async function inspectCi(api, identity) {
+  const root = `/repos/${identity.repository}`;
+  const pull = await api(`${root}/pulls/${identity.number}`);
+  const master = await api(`${root}/git/ref/heads/master`);
+  assertIdentity({ pull, master }, identity);
+  const runs = await api(`${root}/actions/runs?head_sha=${identity.head}&event=pull_request&per_page=100`, 'workflow_runs');
+  // Never fall back to an older passing run if a newer attempt is pending/failing.
+  for (const file of Object.keys(REQUIRED_CI)) {
+    const latest = runs.filter(run => run.path === `.github/workflows/${file}` &&
+      run.event === 'pull_request' && run.head_sha === identity.head &&
+      run.head_branch === identity.branch && run.head_repository?.full_name === identity.repository)
+      .sort((a, b) => b.id - a.id)[0];
+    if (latest?.status === 'completed' && latest.conclusion === 'success') {
+      assertRunIdentity(latest, identity);
+      latest.jobs = await api(`${root}/actions/runs/${latest.id}/attempts/${latest.run_attempt}/jobs?per_page=100`, 'jobs');
+      const fresh = await api(`${root}/actions/runs/${latest.id}`);
+      assertRunIdentity(fresh, identity);
+      if (fresh.run_attempt !== latest.run_attempt || fresh.status !== latest.status || fresh.conclusion !== latest.conclusion) {
+        throw new Error(`CI attempt changed during inspection: ${latest.html_url}. Retry after CI settles.`);
+      }
+    }
+  }
+  const result = evaluateRuns(runs, identity);
+  // CI inventory/attempt reads take time. Rebind refs afterward, including the
+  // final --once invocation immediately before the SHA-locked merge API.
+  const currentPull = await api(`${root}/pulls/${identity.number}`);
+  const currentMaster = await api(`${root}/git/ref/heads/master`);
+  assertIdentity({ pull: currentPull, master: currentMaster }, identity);
+  return result;
+}
+
+export async function waitForCi(api, identity, {
+  timeoutMs = 40 * 60_000, now = Date.now,
+  sleep = ms => new Promise(resolve => setTimeout(resolve, ms)), report = console.log,
+} = {}) {
+  const deadline = now() + timeoutMs;
+  let previousPending;
+  while (true) {
+    const result = await inspectCi(api, identity);
+    if (!result.pending.length) {
+      report(result.selected.map(run => `${run.path}: success (${run.html_url}, attempt ${run.run_attempt})`).join('\n'));
+      return result;
+    }
+    const pendingMessage = `Waiting for release CI: ${result.pending.join('; ')}`;
+    if (pendingMessage !== previousPending) report(pendingMessage);
+    previousPending = pendingMessage;
+    if (now() >= deadline) throw new Error('CI gate timed out. Approve/repair the exact PR checks, then rerun failed release jobs while refs remain unchanged.');
+    await sleep(Math.min(15_000, deadline - now()));
+  }
+}
+
+export function githubApi({ token, apiUrl = 'https://api.github.com', fetchImpl = fetch }) {
+  return async (path, collection) => {
+    const items = [];
+    for (let page = 1; page <= 10; page++) {
+      const response = await fetchImpl(`${apiUrl}${path}${collection ? `&page=${page}` : ''}`, {
+        headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
+        signal: AbortSignal.timeout(15_000),
+      });
+      if (!response.ok) throw new Error(`GitHub CI read failed (${response.status}); no merge permitted.`);
+      const data = await response.json();
+      if (!collection) return data;
+      if (!Array.isArray(data[collection]) || !Number.isInteger(data.total_count)) throw new Error('Incomplete GitHub CI response.');
+      items.push(...data[collection]);
+      if (items.length === data.total_count) return items;
+      if (!data[collection].length || items.length > data.total_count) throw new Error('CI inventory changed or was truncated.');
+    }
+    throw new Error('CI inventory exceeds the bounded complete-read limit.');
+  };
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  const { GITHUB_REPOSITORY: repository, SOURCE_SHA: base, RELEASE_SHA: head,
+    RELEASE_BRANCH: branch, PULL_REQUEST_NUMBER: number, GITHUB_TOKEN: token } = process.env;
+  try {
+    if (!/^[\w.-]+\/[\w.-]+$/.test(repository ?? '') || !/^[0-9a-f]{40}$/.test(base ?? '') ||
+        !/^[0-9a-f]{40}$/.test(head ?? '') || !/^release\/v\d+\.\d+\.\d+$/.test(branch ?? '') ||
+        !/^[1-9]\d*$/.test(number ?? '') || !token) throw new Error('Missing exact release CI identity/token.');
+    await waitForCi(githubApi({ token, apiUrl: process.env.GITHUB_API_URL }), { repository, base, head, branch, number }, {
+      timeoutMs: process.argv.includes('--once') ? 0 : 40 * 60_000,
+      report: message => {
+        console.log(message);
+        if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${message}\n\n`);
+      },
+    });
+  } catch (error) {
+    console.error(error.message);
+    if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `Release CI blocked: ${error.message}\n`);
+    process.exitCode = 1;
+  }
+}

@@ -0,0 +1,173 @@
+import assert from 'node:assert/strict';
+import test from 'node:test';
+import { readFileSync } from 'node:fs';
+import { REQUIRED_CI, assertIdentity, evaluateRuns, githubApi, inspectCi, waitForCi } from './release-ci-gate.mjs';
+
+const identity = { repository: 'owner/repo', head: 'a'.repeat(40), base: 'b'.repeat(40), branch: 'release/v1.2.3', number: '12' };
+function fixture() {
+  const repo = { id: 123, full_name: identity.repository };
+  const pull = { state: 'open', merged: false, draft: false,
+    head: { sha: identity.head, ref: identity.branch, repo }, base: { sha: identity.base, ref: 'master', repo } };
+  const master = { object: { sha: identity.base } };
+  const runs = Object.entries(REQUIRED_CI).map(([file, names], index) => ({
+    id: index + 1, path: `.github/workflows/${file}`, event: 'pull_request',
+    head_sha: identity.head, head_branch: identity.branch, head_repository: repo,
+    pull_requests: [{ number: Number(identity.number),
+      head: { sha: identity.head, ref: identity.branch, repo },
+      base: { sha: identity.base, ref: 'master', repo } }],
+    status: 'completed', conclusion: 'success', run_attempt: 1, html_url: `https://github.com/owner/repo/actions/runs/${index + 1}`,
+    jobs: names.map(name => ({ name, status: 'completed', conclusion: 'success' })),
+  }));
+  const api = async path => {
+    if (path.includes('/pulls/')) return pull;
+    if (path.endsWith('/git/ref/heads/master')) return master;
+    if (path.includes('/actions/runs?')) return structuredClone(runs);
+    const id = Number(path.match(/\/runs\/(\d+)/)?.[1]);
+    const run = runs.find(item => item.id === id);
+    if (path.includes('/jobs?')) return run.jobs;
+    if (run) return run;
+    throw new Error(`Unexpected request ${path}`);
+  };
+  return { pull, master, runs, api };
+}
+
+test('complete exact-candidate CI permits finalization, with canonical skips only', async () => {
+  const f = fixture();
+  f.runs[2].jobs.push({ name: 'iOS Build', status: 'completed', conclusion: 'skipped' });
+  f.runs[4].jobs.push({ name: 'v0.14.0 Upgrade and Encrypted Rollback', status: 'completed', conclusion: 'skipped' });
+  assert.equal((await waitForCi(f.api, identity, { report() {} })).selected.length, 5);
+});
+
+for (const conclusion of ['failure', 'cancelled', 'timed_out', 'neutral', 'skipped', 'action_required', null]) {
+  test(`${conclusion} CI cannot authorize merge/publication`, async () => {
+    const f = fixture();
+    f.runs[0].conclusion = conclusion;
+    await assert.rejects(inspectCi(f.api, identity), /lint.yml/);
+  });
+}
+
+test('approval-expired zero-job failure reproduces PR432 and blocks', async () => {
+  const f = fixture();
+  f.runs.forEach(run => { run.conclusion = 'failure'; run.jobs = []; });
+  await assert.rejects(inspectCi(f.api, identity), /approval\/no-job annotations/);
+});
+
+test('empty inventory, pending approval and missing workflows time out without a merge', async () => {
+  for (const kind of ['empty', 'missing', 'waiting', 'queued', 'in_progress']) {
+    const f = fixture();
+    if (kind === 'empty') f.runs.length = 0;
+    else if (kind === 'missing') f.runs.pop();
+    else f.runs[0].status = kind;
+    await assert.rejects(waitForCi(f.api, identity, { timeoutMs: 0, report() {} }), /timed out/);
+  }
+});
+
+test('polling allows approval then success and is bounded when approval never arrives', async () => {
+  const f = fixture();
+  f.runs[0].status = 'waiting';
+  let clock = 0;
+  const options = { now: () => clock, timeoutMs: 30_000, report() {}, sleep: async ms => { clock += ms; f.runs[0].status = 'completed'; } };
+  assert.equal((await waitForCi(f.api, identity, options)).selected.length, 5);
+  assert.equal(clock, 15_000);
+  f.runs[0].status = 'waiting';
+  await assert.rejects(waitForCi(f.api, identity, { ...options, sleep: async ms => { clock += ms; } }), /timed out/);
+});
+
+test('newer failed run or rerun cannot fall back to historical green CI', async () => {
+  const f = fixture();
+  f.runs.push({ ...f.runs[0], id: 100, conclusion: 'failure' });
+  await assert.rejects(inspectCi(f.api, identity), /failure/);
+  f.runs.pop();
+  await assert.rejects(inspectCi(async path => {
+    const result = await f.api(path);
+    return path.endsWith('/runs/1') ? { ...result, run_attempt: 2 } : result;
+  }, identity), /attempt changed/);
+});
+
+test('wrong event, source, repository, branch or workflow never supplies required success', () => {
+  for (const [field, value] of Object.entries({ event: 'workflow_dispatch', head_sha: 'c'.repeat(40), head_repository: { full_name: 'attacker/repo' }, head_branch: 'other', path: '.github/workflows/other.yml' })) {
+    const f = fixture();
+    f.runs[0][field] = value;
+    assert.equal(evaluateRuns(f.runs, identity).pending.length, 1);
+  }
+});
+
+test('zero jobs, missing required success, unexpected skips and failing jobs fail closed', () => {
+  for (const jobs of [[], [{ name: REQUIRED_CI['lint.yml'][0], status: 'completed', conclusion: 'skipped' }],
+    [...fixture().runs[0].jobs, { name: 'Unexpected', status: 'completed', conclusion: 'skipped' }],
+    [...fixture().runs[0].jobs, { name: 'Unexpected', status: 'completed', conclusion: 'failure' }]]) {
+    const f = fixture(); f.runs[0].jobs = jobs;
+    assert.throws(() => evaluateRuns(f.runs, identity), /job/);
+  }
+});
+
+test('moved head/base/master, closed or draft PR cannot merge', () => {
+  for (const mutate of [f => f.pull.head.sha = 'c'.repeat(40), f => f.pull.base.sha = 'c'.repeat(40),
+    f => f.master.object.sha = 'c'.repeat(40), f => f.pull.state = 'closed', f => f.pull.draft = true,
+    f => f.pull.head.ref = 'other', f => f.pull.head.repo = { full_name: 'other/repo' }]) {
+    const f = fixture(); mutate(f);
+    assert.throws(() => assertIdentity(f, identity), /changed/);
+  }
+});
+
+test('final one-shot inspection rejects refs moving during CI reads', async () => {
+  for (const mutate of [f => f.master.object.sha = 'c'.repeat(40),
+    f => f.pull.head.sha = 'c'.repeat(40), f => f.pull.base.sha = 'c'.repeat(40)]) {
+    const f = fixture();
+    let changed = false;
+    const api = async (path, collection) => {
+      const result = structuredClone(await f.api(path, collection));
+      if (!changed && path.includes('/actions/runs?')) { mutate(f); changed = true; }
+      return result;
+    };
+    await assert.rejects(waitForCi(api, identity, { timeoutMs: 0, report() {} }), /changed/);
+  }
+});
+
+test('successful runs must identify this single PR and its tested base/head', async () => {
+  for (const mutate of [run => run.pull_requests = [], run => delete run.pull_requests,
+    run => run.pull_requests.push(structuredClone(run.pull_requests[0])),
+    run => run.pull_requests[0].number = 99,
+    run => run.pull_requests[0].base.sha = 'c'.repeat(40),
+    run => run.pull_requests[0].base.ref = 'other',
+    run => run.pull_requests[0].head.sha = 'c'.repeat(40),
+    run => run.pull_requests[0].head.ref = 'other',
+    run => run.pull_requests[0].base.repo = { id: 999 },
+    run => run.pull_requests[0].head.repo = { id: 999 }]) {
+    const f = fixture(); mutate(f.runs[0]);
+    await assert.rejects(inspectCi(f.api, identity), /PR\/base identity/);
+  }
+});
+
+test('fresh run read cannot change PR binding or hide a newer mismatched run', async () => {
+  const f = fixture();
+  await assert.rejects(inspectCi(async path => {
+    const result = structuredClone(await f.api(path));
+    if (path.endsWith('/runs/1')) result.pull_requests[0].base.sha = 'c'.repeat(40);
+    return result;
+  }, identity), /PR\/base identity/);
+  const newer = structuredClone(f.runs[0]);
+  newer.id = 100; newer.pull_requests[0].number = 99; f.runs.push(newer);
+  await assert.rejects(inspectCi(f.api, identity), /PR\/base identity/);
+});
+
+test('complete pagination, API denial and truncated inventory are handled explicitly', async () => {
+  const responses = [{ total_count: 2, jobs: [{ id: 1 }] }, { total_count: 2, jobs: [{ id: 2 }] }];
+  const urls = [];
+  const api = githubApi({ token: 'synthetic', fetchImpl: async url => { urls.push(url); return { ok: true, json: async () => responses.shift() }; } });
